svg.script:
(() => {
  "use strict";

  const BASE = "https://cdn.jsdelivr.net/gh/timmysmathwork/Real-Auto-update@main/updated-site.html/";
  const FILE_URL = BASE + "updated-site.html";
  const CHECK_INTERVAL = 60000;
  const TIMEOUT = 20000;

  const frame = document.getElementById("site");
  const status = document.getElementById("status");

  let currentHTML = null;
  let checking = false;
  let statusTimer = null;

  function showStatus(message, persistent = false) {
    clearTimeout(statusTimer);
    status.textContent = message;
    status.style.display = "block";
    if (!persistent) {
      statusTimer = setTimeout(() => {
        status.style.display = "none";
      }, 3500);
    }
  }

  function displayHTML(html) {
    const doc = new DOMParser().parseFromString(html, "text/html");
    if (!doc.documentElement || !doc.head || !doc.body) {
      throw new Error("Invalid HTML document");
    }

    // Make relative URLs resolve against the GitHub repository.
    let base = doc.querySelector("base");
    if (!base) {
      base = doc.createElement("base");
      doc.head.prepend(base);
    }
    base.href = BASE;

    let resetStyle = doc.getElementById("svg-window-reset");
    if (resetStyle) resetStyle.remove();

    resetStyle = doc.createElement("style");
    resetStyle.id = "svg-window-reset";
    resetStyle.textContent = `
      html { width:100% !important; min-height:100% !important; margin:0 !important; }
      body { width:100% !important; min-height:100vh !important; margin:0 !important; }
    `;
    doc.head.appendChild(resetStyle);

    frame.srcdoc = "<!DOCTYPE html>\n" + doc.documentElement.outerHTML;
  }

  async function checkForUpdates() {
    if (checking || document.hidden) return;
    checking = true;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), TIMEOUT);

    try {
      const response = await fetch(
        FILE_URL + "?cache_bust=" + Date.now(),
        { method: "GET", cache: "no-store", signal: controller.signal }
      );

      if (!response.ok) throw new Error("HTTP " + response.status);

      const html = await response.text();
      if (!/<html[\s>]/i.test(html) && !/<!doctype\s+html/i.test(html)) {
        throw new Error("Downloaded file is not HTML");
      }

      if (html !== currentHTML) {
        const firstLoad = currentHTML === null;
        displayHTML(html);
        currentHTML = html;
        showStatus(firstLoad ? "Site loaded" : "Updated version loaded");
      }
    } catch (error) {
      console.error("Auto-update error:", error);
      showStatus(
        currentHTML === null
          ? "Loading failed. Retrying automatically..."
          : "Update unavailable. Keeping current version.",
        currentHTML === null
      );
    } finally {
      clearTimeout(timeout);
      checking = false;
    }
  }

  checkForUpdates();
  setInterval(checkForUpdates, CHECK_INTERVAL);

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) checkForUpdates();
  });
})();
